					<div class="e-con-inner">
				<div class="elementor-element elementor-element-c594b1d elementor-widget elementor-widget-heading" data-id="c594b1d" data-element_type="widget" data-widget_type="heading.default">
				<div class="elementor-widget-container">
					<h2 class="elementor-heading-title elementor-size-default">FAQs</h2>				</div>
